+impl<'s> Drop for Worker<'s> {
+    fn drop(&mut self) {
+        // If this worker is being dropped because the thread is unwinding
+        // from a panic (typically in the caller's visitor), then it never
+        // got to tell the other workers that it is finished. Since it still
+        // counts as an active worker, the others would wait for it forever.
+        // So tell everyone to quit. The panic itself is propagated to the
+        // caller of `WalkParallel::visit` when the thread is joined.
+        if std::thread::panicking() {
+            self.quit_now();
+        }
+    }
+}
